from pathlib import Path
import json,csv,hashlib,gzip,time
R=Path(__file__).resolve().parents[1];D=R/'data_recovery';OUT=R/'runs/EG_SUB25_V1';E=OUT/'evaluation';BAD=OUT/'bad_cases'
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
result=json.loads((E/'evaluation_results.json').read_text());bc=json.loads((D/'BAD_CASE_COMPLETE.json').read_text());train=json.loads((D/'TRAINING_COMPLETE.json').read_text());assert result['status']=='PASS' and bc['status']=='PASS'
receipts={}
for pattern in ['infer_*.json','official_api_*.json','summarize_evaluation.json','replay_bad_cases.json','analyze_bad_cases.json']:
 for p in (R/'receipts').glob(pattern):
  x=json.loads(p.read_text());assert x['status']=='PASS',str(p);receipts[p.stem]=x
paths=[]
for base in [E/'predictions',E/'inputs',E/'results',BAD]:paths.extend(p for p in base.rglob('*') if p.is_file())
paths.extend(p for p in (R/'logs').iterdir() if p.is_file() and p.name.startswith(('infer_','official_api_','summarize_evaluation','replay_bad_cases','analyze_bad_cases','run_evaluation')))
paths=sorted(set(paths));index=E/'EVALUATION_ARTIFACT_INDEX.csv.gz'
with gzip.open(index,'wt',newline='') as f:
 w=csv.writer(f);w.writerow(['absolute_path','bytes','sha256'])
 for p in paths:w.writerow([str(p),p.stat().st_size,sha(p)])
index_info={'path':str(index),'files':len(paths),'total_bytes':sum(p.stat().st_size for p in paths),'index_sha256':sha(index),'coverage':'Immutable input caches,predictions,native AP/evaluated-candidate tensors,bad-case tensors/observations/figures and evaluation logs;training checkpoint hashes are in TRAINING_COMPLETE.json'}
(E/'EVALUATION_ARTIFACT_INDEX.json').write_text(json.dumps(index_info,indent=2))
lines=['# EG-SUB25-V1 evaluation and diagnostic report','','Status: COMPLETE for the registered25%subset training,development evaluation,and bounded paired diagnostics. This is not a full-data paper reproduction.','','## Training','','One seed20261015;50metadata-selected scenes x128uniform frames=6400;10epochs,batch4,16000updates,Adam0.001,original cosine schedule. Training took10322.36s(2h52m). Epoch mean loss decreased4.681914 to3.267090. All10checkpoints strictly loaded and finite;final real-data decode and all16000logged losses passed. Data,supervision,forward,backward and checkpoint gates passed before formal training. No additional training was started.','','## AP results','','Percent units. AP averages complete256frames per scene,official top1..50precision and six friction thresholds. AP0.4/0.8 select the corresponding native thresholds.','','|Partition/model|Scenes|Frames|AP|AP0.4|AP0.8|Forward+decode ms/frame|','|---|---|---:|---:|---:|---:|---:|']
for part,roles in result['summaries'].items():
 for role,x in roles.items():lines.append(f"|{part}/{role}|{','.join(map(str,x['scenes']))}|{x['frames']}|{x['ap_percent']:.4f}|{x['ap04_percent']:.4f}|{x['ap08_percent']:.4f}|{x['forward_decode_ms_per_frame']:.3f}|")
lines+=['','The development scenes are held out from this subset model but originate in the official training split. They cannot measure official Novel generalization. Official pretrained weights were evaluated only on the fixed Seen/Novel scenes,not on development training scenes. The two-scene Seen/Novel summaries are exploratory diagnostics,not full split AP and not directly comparable with README62.59/51.73/19.54.','','|Partition/scene|Subset AP|Official AP|Subset minus official,pp|','|---|---:|---:|---:|']
for x in result['paired_scene_results']:lines.append(f"|{x['partition']}/{x['scene']:04d}|{x['subset_ap_percent']:.4f}|{x['official_ap_percent']:.4f}|{x['subset_minus_official_pp']:.4f}|")

lines+=['','## Validity and compatibility','','The model remains the pinned official EconomicGrasp architecture/loss/decoder. All 4608 predictions are finite 1024x17 grasp arrays. Both models use identical cached point-cloud inputs in paired scenes; input-manifest hashes match. The installed native GraspNetEval.eval_scene implementation is unmodified and its hash is recorded. All 18 scene evaluations completed all 256 frames; serialized friction/collision results reproduce every native precision entry exactly. No frame was omitted. Official raw confidence is a logit-weighted sum, not a probability.','','Inference used an external driver with original Dataset, model, pred_decode and native GraspGroup serialization to support the frozen manifest and immutable paired inputs. Collision threshold 0 matches the official default; physical collision and force-closure evaluation remain native API. GraspNetAPI accepts development training scenes through split=all; adapter model/pose preflight passed. AP process/thread limits, nice priority and GPU selection are engineering settings only. No new score calibration, NMS, metric definition or successful-case filtering was introduced.','','The earlier Smoke empty-candidate FPS error was addressed by aligning the fixed 80-frame Smoke order with official shuffling and adding an explicit empty-set error guard. No fallback or threshold change was used; formal training and evaluation did not encounter that guard. Compatibility/source patches and upstream identity are archived.','','## Bad Case findings','','All 1024 paired diagnostic frames are summarized with the operational top1 criterion: noncollision and 0<required friction<=0.4. This supplements continuous AP and does not estimate real robot success. Twelve selected paired frames follow the predeclared two-lowest-plus-median rule per scene. See bad_case_report.md and derived figures.','','|Partition|Both valid|Subset invalid / official valid|Both invalid|Subset valid / official invalid|','|---|---:|---:|---:|---:|']
for part,c in bc['paired_top1_categories'].items():lines.append(f"|{part}|{c['both_valid04']}|{c['subset_invalid_official_valid04']}|{c['both_invalid04']}|{c['subset_valid_official_invalid04']}|")
lines+=['','Observed ordering, collision, point coverage and nearby-center pose contrasts are documented separately from hypotheses about network modules. Case selection is posthoc and exploratory. The official model differs in training amount and possibly original random seed/history, so paired differences do not isolate a module cause. Scene-complexity proxies do not measure causal occlusion effects. Intermediate replay agreement is explicitly recorded; unmatched replays cannot prove the original internal path.','','## Cost and artifacts','','|Job|Wall seconds|Own peak RSS GiB|Own sampled peak GPU MiB|','|---|---:|---:|---:|']
for name,x in receipts.items():lines.append(f"|{name}|{x['wall_seconds']:.2f}|{x['peak_own_rss_bytes']/2**30:.3f}|{x['peak_own_gpu_memory_mib']}|")
lines+=['','Inference GPU 0 was shared under user authorization; foreign loads were recorded and not stopped. AP used four low-priority CPU workers with one BLAS/OpenMP thread each during high shared load. Timings are measured under these conditions; forward/decode excludes data loading and native AP. Raw storage identities are in EVALUATION_ARTIFACT_INDEX.json and its compressed CSV; training weights/logs remain under '+str(OUT/'train')+'.','','## Research decision','','This run provides a reproducible lightweight baseline and paired exploratory evidence. It does not establish full-data paper reproduction, full Novel AP, convergence across seeds, or a module-level failure mechanism. Review the measured official-versus-subset gap and ranking/pose observations before selecting any next experiment. No 75-scene expansion, new method, new seed or retraining was automatically launched.','','Branch: https://github.com/rollinpioneer/graph/tree/codex/eg-sub25-v1-20261015 . Source upstream 4119bdcd6bf5d3712a110f78ca87504dd359eec0; frozen split SHA256 bdf75f905271f4672de2407da3c095f257082fa46cd4099d9f16ebecbd258157.']
(OUT/'final_reproduction_report.md').write_text('\n'.join(lines)+'\n')
result['bad_case_status']='COMPLETE';result['bad_case_cases']=12;result['artifact_index']=index_info
(E/'evaluation_results.json').write_text(json.dumps(result,indent=2));(D/'EVALUATION_COMPLETE.json').write_text(json.dumps(result,indent=2))
status=json.loads((D/'EVALUATION_STATUS.json').read_text());status.update(status='COMPLETE',stage='COMPLETE',completed_unix=time.time(),bad_cases=12);(D/'EVALUATION_STATUS.json').write_text(json.dumps(status,indent=2))
status=json.loads((D/'PIPELINE_STATUS.json').read_text());status.update(status='COMPLETE',stage='COMPLETE',evaluation_validation='PASS',bad_case_analysis='COMPLETE',updated_unix=time.time());status['completed_stages']=['REAL_80FRAME_SMOKE','FORMAL_TRAINING','DEVELOPMENT_AP','PAIRED_SEEN_NOVEL_AP','EXPLORATORY_BAD_CASES'];(D/'PIPELINE_STATUS.json').write_text(json.dumps(status,indent=2))
print('FINAL_REPORT_COMPLETE',index_info,flush=True)
